","codfor":"708","before":1,"after":48}]'::jsonb)
 AS r(codigo text,descricao text,codfor text,before numeric,after numeric);
DO $$DECLARE n integer; BEGIN
 SELECT count(*) INTO n FROM verified_packaging_repair r JOIN public.dim_produtos p USING(codigo)
 WHERE p.descricao=r.descricao AND p.codfor=r.codfor AND p.qtde_embalagem_master=r.before;
 IF n<>188 THEN RAISE EXCEPTION 'Packaging changed since verification; refusing partial repair (%).',n;END IF;
 UPDATE public.dim_produtos p SET qtde_embalagem_master=r.after FROM verified_packaging_repair r
 WHERE p.codigo=r.codigo AND p.descricao=r.descricao AND p.codfor=r.codfor AND p.qtde_embalagem_master=r.before;
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>188 THEN RAISE EXCEPTION 'Unexpected repaired product count: %',n;END IF;
 IF EXISTS(SELECT 1 FROM packaging_summary_guard b FULL JOIN
 (SELECT ano,mes,count(*) row_count,sum(vlvenda) revenue,sum(peso) weight FROM public.data_summary GROUP BY 1,2)a USING(ano,mes)
 WHERE b.row_count IS DISTINCT FROM a.row_count OR b.revenue IS DISTINCT FROM a.revenue OR b.weight IS DISTINCT FROM a.weight)
 THEN RAISE EXCEPTION 'Non-box totals changed; rolling back repair';END IF;
END;$$;
SELECT jsonb_build_object('products_corrected',(SELECT count(*) FROM verified_packaging_repair),
 'revenue_and_weight_preserved',true,
 'spicy',(SELECT jsonb_agg(jsonb_build_object('code',codigo,'units_per_box',qtde_embalagem_master))
 FROM public.dim_produtos WHERE codigo IN('6299','6300'))) result;
COMMIT;
